const stone = find_block({ names: ['stone', 'cobblestone', 'andesite', 'diorite'], max_distance: 32 });
if (!stone) {
  return { done: false, detail: 'no stone within 32 blocks' };
}
await dig(stone.x, stone.y, stone.z);
const left = await leave_at_depot('cobblestone', 1);
if (!left.ok) {
  return { done: false, detail: left.detail };
}
return { done: true, detail: 'mined stone and left it at the depot' };
